INSERT INTO changelog (title, body, created_at) VALUES ('Кампанії: усі назви для Ads Manager', 'В оголошенні зверху — блок «Що вставити в Ads Manager»: назва оголошення з кодом AD-N, сторінка Facebook, формат, назва файлу креативу, папка кампанії, лід-форма, кнопка, посилання — видно завжди, навіть до текстів. На вкладці «Кампанія» — «Усі назви»: кампанія → групи → оголошення по черзі з кнопками «Копіювати». Назви форм від Джері тепер «назва · AD-N», версії веде система (без v1/v2 у назві).', datetime('now'));
